create-asset.doc:
- url {string} The URL of the asset, for example: db://assets/abc.json
- content {string | null} Writes the contents of a string to a file, or creates a new folder if null
- option {AssetOperationOption}
    - option.overwrite {boolean} If overwrite is enforced, the default is false
    - option.rename {boolean} Default false if the conflict is automatically renamed

@returns {AssetInfo} Returns an asset information

import-asset.doc:
- source {string} The absolute address of the local file
- target {string} The URL address to import into the database
- option {AssetOperationOption}
    - option.overwrite {boolean} If overwrite is enforced, the default is false
    - option.rename {boolean} Default false if the conflict is automatically renamed

@returns {AssetInfo} Returns an asset information

copy-asset.doc:
- source {string} The URL path of the source resource, for example: db://assets/abc.json
- target {string} The URL of the destination location copied to
- option {AssetOperationOption}
    - option.overwrite {boolean} If overwrite is enforced, the default is false
    - option.rename {boolean} Default false if the conflict is automatically renamed

@returns {AssetInfo} Returns an asset information

move-asset.doc:
- source {string} The URL path of the source resource that needs to be moved, for example: db://assets/abc.json
- target {string} The URL of the destination location moved to
- option {AssetOperationOption}
    - option.overwrite {boolean} If overwrite is enforced, the default is false
    - option.rename {boolean} Default false if the conflict is automatically renamed

@returns {AssetInfo} Returns an asset information

save-asset-meta.doc:
- urlOrUUID {string} The URL or UUID of the asset
- content {string} The serialized content string of the asset Meta

@returns {AssetInfo} Returns an asset information

reset-property.doc:
- options {SetPropertyOptions}
                    - uuid {string} uuid of the object
                    - path {string} search path of the property

move-array-element.doc:
- options {MoveArrayOptions}
                    - uuid {string} uuid of node
                    - path {string} search path of array
                    - target {number} original index of the target item
                    - offset {number} move offset

                @returns {boolean} whether it is successful

remove-array-element.doc:
- options {MoveArrayOptions}
                    - uuid {string} uuid of node
                    - path {string} search path of array
                    - index {number} index of item

                @returns {boolean} whether it is successful

paste-node.doc:
- options {PasteNodeOptions}
                    - target {string} uuid of target node
                    - uuids {string | string[]} uuid of node that is copied
                    - keepWorldTransform {boolean} whether to keep the world transform

                @returns {string | string[]} uuid of new node

set-parent.doc:
- options {CutNodeOptions}
                    - parent {string} uuid of parent
                    - uuids {string|string[]} uuid of the node that need to set
                    - keepWorldTransform {boolean} whether to keep the world transform

                @returns {string | string[]} uuid of node

reset-component.doc:
- options {ResetComponentOptions}
                    - uuid {string} uuid of component

                @returns {boolean} whether it is successful

restore-prefab.doc:
- uuid {string} uuid of node
                - assetUuid {string} uuid of asset

                @returns {boolean} whether it is successful

create-component.doc:
- options {CreateComponentOptions}
                    - uuid {string} uuid of node
                    - component {string} classId (cid) (is recommended) or className

remove-component.doc:
- options {CreateComponentOptions}
                    - uuid {string} uuid of node
                    - component {string} classId (cid) (is recommended) or className

query-components.doc:
@returns {[Object]}
                - name {string} name of component
                - path {string} path in menu
